<?php declare(strict_types=1); namespace App\Core\Middleware; use App\Core\Authorization; use App\Core\Request; use App\Core\Response; final class PermissionMiddleware { public function __construct(private readonly Authorization $authorization){} public function handle(Request $request,\Closure $next,?string $permission=null):Response{if($permission!==null)$this->authorization->authorize($permission);return $next($request);} }